import { expect, test, uniqueName } from "../../fixtures";

const cases: Array<{ field: string; value: unknown }> = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
];

test.describe("manage vendors", () => {
  for (const { field, value } of cases) {
    test(`rejects a vendor with invalid ${field}`, { tag: "@VEN-02" }, async ({ apiAs }) => {
      // Arrange: a valid vendor body, with only the field under test made invalid
      const member = await apiAs("member");
      const body: Record<string, unknown> = {
        name: uniqueName("Vendor"),
        category: "software",
        contact_email: `ops-${Date.now().toString(36)}@vendor.test`,
      };
      body[field] = value;

      // Act
      const response = await member.post("/api/vendors", { data: body });
      const text = await response.text();

      // Assert
      expect(response.status(), text).toBe(422);
      const payload = JSON.parse(text) as {
        error?: { code?: string; details?: unknown };
        detail?: Array<{ loc?: unknown[]; type?: string }>;
      };
      const code = payload.error?.code ?? "validation_error";
      expect(code, text).toBe("validation_error");
      expect(text, `error should name field "${field}"`).toContain(field);
      if (payload.detail) {
        expect(
          payload.detail.some((d) => d.loc?.includes(field)),
          text,
        ).toBe(true);
      }
    });
  }
});
